//! `librosa` rhythm references (fixture `rhythm.json`, generated by
//! `cases/rhythm.py`): onset strength (single and multi-band), `util.peak_pick`,
//! `onset_detect` / `onset_backtrack`, tempo frequencies, tempograms, `tempo`,
//! `beat_track`, `plp`, `tempogram_ratio`, `hybrid_tempogram` and `metrogram`.
//!
//! Tolerances:
//! - Onset envelopes (`1e-10` peak-relative): they are means of positive dB
//!   differences of the mel power spectrogram, which itself matches librosa to
//!   ~1e-12 (`spectrum` area: FFT butterfly order, matrix-product order). A dB
//!   value of ~-80..+40 dB with ~1e-13 absolute error gives envelopes far inside
//!   1e-10 of their peak.
//! - Tempograms, Fourier tempograms, PLP and the tempogram variants (`1e-9`
//!   peak-relative; `hybrid_tempogram` see its comment): computed from
//!   librosa's own stored envelope, so only FFT round-off (pocketfft vs realfft) and
//!   libm `exp`/`cos` ulps remain, amplified at most by the column normalisation.
//! - Event outputs (peaks, onsets, beats) and tempi are compared EXACTLY: the
//!   decisions (local maxima, thresholds, argmax over the BPM grid, DP choices) are
//!   made on values that agree to ~1e-12, with no near-ties in these signals, and the
//!   kernels reproduce librosa's numba arithmetic order (sequential means, numpy
//!   pairwise sums, `float32` tightness, round-half-even).
//!
//! - `float32` cases: `AudioSamples<f32>` (computed in `f32`) against librosa on
//!   `y.astype(np.float32)`; tolerances are derived from f32 round-off next to
//!   their constants. Events, tempi and beats are compared exactly there too.
//!
//! Measured errors are printed with `--nocapture`.

use audio_samples::operations::rhythm::{
    Aggregate, AudioRhythm, BeatTrackConfig, FourierTempogramConfig, HybridTempogramConfig,
    OnsetDetectConfig, OnsetStrengthConfig, PeakPickConfig, PeakPickMethod, PlpConfig, TempoConfig,
    TempogramConfig, TempogramRatioConfig, beat_track_from_envelope, beat_track_with_bpm,
    fourier_tempo_frequencies, fourier_tempogram_from_envelope, hybrid_tempogram_from_envelope,
    metrogram, onset_backtrack, onset_detect_from_envelope, peak_pick, plp_from_envelope,
    tempo_frequencies, tempo_from_envelope, tempogram_from_envelope,
    tempogram_ratio_from_tempogram,
};
use audio_samples::operations::spectrum::{MelSpectrogramConfig, StftConfig};
use audio_samples::{AudioSamples, nzu};
use ndarray::{Array2, Array3, s};
use serde_json::Value;

use crate::common::{
    arr2, arr3, assert_close, carr2, errors, f64s, load, mono, signal, sr, stereo,
};

// float32 tolerances (peak-relative) for `float32_input`; f32 eps = 1.19e-7.
//
// Onset envelopes: measured worst 4.4e-6 (`mix`), 1.4e-6 or less elsewhere. The
// envelope is a mean of differences of dB values of up to ~80 dB in magnitude,
// where one f32 ulp is 7.6e-6 dB; librosa and this crate round the mel power
// (different FFTs, same f32 basis values) and the log10 independently, so a
// difference carries ~1e-5 dB absolute error. `mix` has a steady spectrum and
// an envelope peak of only ~2 dB, which turns that into ~5e-6 relative. Bound:
// 2e-5 (a factor of 4.6).
const TOL_F32_ENVELOPE: f64 = 2e-5;
// Tempogram and Fourier tempogram magnitude: measured worst 1.4e-6 (`mix`
// tempogram; librosa's autocorrelation runs in float64, ours in f32) and 7.1e-7
// (Fourier). The input envelope's own f32 error (above) propagates, plus
// O(log2(768) * eps) ~ 1.1e-6 from the f32 FFTs. Bound: 5e-6 (~42 eps, a
// factor of 3.7).
const TOL_F32_TEMPOGRAM: f64 = 5e-6;
// PLP: measured worst 3.6e-7 (both sides in float32: STFT, peak selection,
// inverse STFT of 384-point frames, max-normalisation). Bound: 2e-6 (~17 eps,
// a factor of 5.6).
const TOL_F32_PLP: f64 = 2e-6;

fn fixture() -> &'static Value {
    static F: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    F.get_or_init(|| load("rhythm"))
}

fn usizes(v: &Value) -> Vec<usize> {
    v.as_array()
        .unwrap_or_else(|| panic!("expected array, got {v}"))
        .iter()
        .map(|x| x.as_u64().expect("index") as usize)
        .collect()
}

/// A scalar or one-element list.
fn scalar(v: &Value) -> f64 {
    v.as_f64().unwrap_or_else(|| f64s(v)[0])
}

fn check(what: &str, actual: &[f64], expected: &[f64], rtol: f64) {
    let (abs, rel) = errors(actual, expected);
    println!("{what}: max abs {abs:.3e}, peak-rel {rel:.3e}");
    assert_close(what, actual, expected, rtol, 0.0);
}

fn onset_cfg(case: &str) -> OnsetStrengthConfig {
    let d = OnsetStrengthConfig::librosa();
    match case {
        "default" => d,
        "lag2" => d.with_lag(nzu!(2)),
        "max_size3" => d.with_max_size(nzu!(3)),
        "median" => d.with_aggregate(Some(Aggregate::Median)),
        "nocenter" => d.with_center(false),
        "detrend" => d.with_detrend(true),
        "hop256_nfft1024" => d.with_mel(
            MelSpectrogramConfig::librosa().with_stft(
                StftConfig::librosa()
                    .with_n_fft(nzu!(1024))
                    .with_hop_length(Some(nzu!(256))),
            ),
        ),
        other => panic!("unknown case {other}"),
    }
}

fn env_row(audio: &AudioSamples<'_, f64>, cfg: &OnsetStrengthConfig) -> Vec<f64> {
    audio.onset_strength(cfg).unwrap().row(0).to_vec()
}

#[test]
fn onset_strength() {
    let f = &fixture()["onset_strength"];
    for sig in ["clicks120", "notes", "mix"] {
        let a = mono(sig);
        for (case, expected) in f[sig].as_object().unwrap() {
            let env = a.onset_strength(&onset_cfg(case)).unwrap();
            assert_eq!(env.nrows(), 1);
            // Mel/dB round-off ~1e-13 dB (see module doc).
            check(
                &format!("onset_strength {sig} {case}"),
                env.as_slice().unwrap(),
                &f64s(expected),
                1e-10,
            );
        }
    }
    let env = stereo()
        .onset_strength(&OnsetStrengthConfig::librosa())
        .unwrap();
    let e = arr2(&f["stereo"]["default"]);
    assert_eq!(env.dim(), e.dim());
    check(
        "onset_strength stereo",
        env.as_slice().unwrap(),
        e.as_slice().unwrap(),
        1e-10,
    );
}

#[test]
fn onset_strength_multi() {
    let f = &fixture()["onset_strength_multi"];
    let bounds = usizes(&f["bounds"]);
    let notes = mono("notes");
    let d = OnsetStrengthConfig::librosa();
    let cases: Vec<(&str, Array3<f64>, Array3<f64>)> = vec![
        (
            "notes_default",
            notes.onset_strength_multi(&d, None).unwrap(),
            arr2(&f["notes_default"]).insert_axis(ndarray::Axis(0)),
        ),
        (
            "notes_bands",
            notes.onset_strength_multi(&d, Some(&bounds)).unwrap(),
            arr2(&f["notes_bands"]).insert_axis(ndarray::Axis(0)),
        ),
        (
            "notes_bands_messy",
            notes
                .onset_strength_multi(
                    &d.clone().with_aggregate(Some(Aggregate::Max)),
                    Some(&[64, 0, 64, 200, 20]),
                )
                .unwrap(),
            arr2(&f["notes_bands_messy"]).insert_axis(ndarray::Axis(0)),
        ),
        (
            "stereo_bands",
            stereo().onset_strength_multi(&d, Some(&bounds)).unwrap(),
            arr3(&f["stereo_bands"]),
        ),
    ];
    for (name, actual, expected) in cases {
        assert_eq!(actual.dim(), expected.dim(), "{name} shape");
        // Mel/dB round-off (see module doc).
        check(
            &format!("onset_strength_multi {name}"),
            actual.as_standard_layout().as_slice().unwrap(),
            expected.as_slice().unwrap(),
            1e-10,
        );
    }
    let step = f["notes_no_aggregate_row_step"].as_u64().unwrap() as usize;
    let full = notes
        .onset_strength_multi(&d.with_aggregate(None), None)
        .unwrap();
    let sub = full.slice(s![0, ..;step, ..]).to_owned();
    let e = arr2(&f["notes_no_aggregate"]);
    assert_eq!(sub.dim(), e.dim());
    check(
        "onset_strength_multi no aggregate",
        sub.as_slice().unwrap(),
        e.as_slice().unwrap(),
        1e-10,
    );
}

#[test]
fn peak_pick_exact() {
    let f = &fixture()["peak_pick"];
    let x = f64s(&f["x"]);
    for (name, case) in f["cases"].as_object().unwrap() {
        let p = &case["params"];
        let get = |k: &str| p[k].as_u64().unwrap() as usize;
        let method = match p.get("method").and_then(Value::as_str) {
            None | Some("greedy") => PeakPickMethod::Greedy,
            Some("dp_count") => PeakPickMethod::DpCount,
            Some("dp_value") => PeakPickMethod::DpValue,
            Some(m) => panic!("unknown method {m}"),
        };
        let cfg = PeakPickConfig {
            pre_max: get("pre_max"),
            post_max: get("post_max"),
            pre_avg: get("pre_avg"),
            post_avg: get("post_avg"),
            delta: p["delta"].as_f64().unwrap(),
            wait: get("wait"),
            method,
        };
        assert_eq!(
            peak_pick(&x, &cfg).unwrap(),
            usizes(&case["peaks"]),
            "peak_pick {name}"
        );
    }
}

#[test]
fn onset_detect_exact() {
    let f = &fixture()["onset_detect"];
    let hop = nzu!(512);
    let srf = f64::from(sr());
    for sig in ["clicks120", "notes", "mix"] {
        let g = &f[sig];
        let a = mono(sig);
        let env = env_row(&a, &OnsetStrengthConfig::librosa());
        let d = OnsetDetectConfig::librosa();
        let det = |cfg: &OnsetDetectConfig, energy: Option<&[f64]>| {
            onset_detect_from_envelope(&env, srf, hop, cfg, energy).unwrap()
        };
        assert_eq!(det(&d, None), usizes(&g["frames"]), "{sig} frames");
        let bt = d.clone().with_backtrack(true);
        assert_eq!(det(&bt, None), usizes(&g["backtrack"]), "{sig} backtrack");
        let rms = f64s(&g["rms"]);
        assert_eq!(
            det(&bt, Some(&rms)),
            usizes(&g["backtrack_rms"]),
            "{sig} backtrack rms"
        );
        let nn = d
            .clone()
            .with_normalize(false)
            .with_peak_pick(Some(PeakPickConfig::for_onsets(srf, hop).with_delta(0.5)));
        assert_eq!(
            det(&nn, None),
            usizes(&g["no_normalize"]),
            "{sig} no normalize"
        );
        let custom = d.clone().with_peak_pick(Some(PeakPickConfig {
            pre_max: 3,
            post_max: 3,
            pre_avg: 5,
            post_avg: 5,
            delta: 0.2,
            wait: 4,
            method: PeakPickMethod::Greedy,
        }));
        assert_eq!(det(&custom, None), usizes(&g["custom"]), "{sig} custom");

        // Through the trait: also equal to librosa's float32-mel-basis result.
        let ev = a.onset_detect(&d).unwrap();
        assert_eq!(ev.frames, usizes(&g["frames"]), "{sig} trait");
        assert_eq!(ev.frames, usizes(&g["from_y_f32basis"]), "{sig} f32 basis");
        assert_eq!(ev.samples(), usizes(&g["samples"]), "{sig} samples");
        // frames * hop / sr: one division, identical in both.
        assert_eq!(ev.times(), f64s(&g["time"]), "{sig} time");
    }
    // onset_backtrack directly on the stored rms.
    let g = &f["notes"];
    let rms = f64s(&g["rms"]);
    assert_eq!(
        onset_backtrack(&usizes(&g["frames"]), &rms),
        usizes(&g["backtrack_rms"])
    );
}

#[test]
fn tempo_frequency_grids() {
    let f = &fixture()["tempogram"]["tempo_frequencies"];
    let t = tempo_frequencies(384, nzu!(512), 22050.0);
    assert!(t[0].is_infinite());
    // Same single division as numpy.
    assert_eq!(t[1..].to_vec(), f64s(&f["t384_from1"]));
    let t = tempo_frequencies(10, nzu!(256), 16000.0);
    assert_eq!(t[1..].to_vec(), f64s(&f["t10_hop256_sr16000_from1"]));
    assert_eq!(
        fourier_tempo_frequencies(22050.0, nzu!(512), nzu!(384)),
        f64s(&f["f384"])
    );
    assert_eq!(
        fourier_tempo_frequencies(16000.0, nzu!(256), nzu!(63)),
        f64s(&f["f63_hop256_sr16000"])
    );
}

#[test]
fn tempograms() {
    let f = &fixture()["tempogram"];
    for sig in ["clicks120", "notes"] {
        let g = &f[sig];
        let env =
            Array2::from_shape_vec((1, f64s(&g["envelope"]).len()), f64s(&g["envelope"])).unwrap();
        let (bs, fs) = (
            g["bin_step"].as_u64().unwrap() as usize,
            g["frame_step"].as_u64().unwrap() as usize,
        );
        let tg = tempogram_from_envelope(env.view(), &TempogramConfig::librosa()).unwrap();
        let shape: Vec<usize> = usizes(&g["tempogram_shape"]);
        assert_eq!([tg.dim().1, tg.dim().2], [shape[0], shape[1]]);
        let sub = tg.slice(s![0, ..;bs, ..;fs]).to_owned();
        // FFT round-off on librosa's exact envelope (module doc).
        check(
            &format!("tempogram {sig}"),
            sub.as_slice().unwrap(),
            arr2(&g["tempogram"]).as_slice().unwrap(),
            1e-9,
        );

        let cfg = TempogramConfig::librosa()
            .with_win_length(nzu!(32))
            .with_center(false)
            .with_norm(Some(2.0));
        let tg = tempogram_from_envelope(env.view(), &cfg).unwrap();
        let e = arr2(&g["tempogram_w32_nocenter_l2"]);
        assert_eq!((tg.dim().1, tg.dim().2), e.dim());
        check(
            &format!("tempogram w32 l2 {sig}"),
            tg.as_slice().unwrap(),
            e.as_slice().unwrap(),
            1e-9,
        );

        let cfg = TempogramConfig::librosa()
            .with_win_length(nzu!(33))
            .with_window(audio_samples::operations::filterbanks::Window::Hamming)
            .with_norm(None);
        let tg = tempogram_from_envelope(env.view(), &cfg).unwrap();
        let e = arr2(&g["tempogram_w33_hamming_nonorm"]);
        assert_eq!((tg.dim().1, tg.dim().2), e.dim());
        check(
            &format!("tempogram w33 hamming {sig}"),
            tg.as_slice().unwrap(),
            e.as_slice().unwrap(),
            1e-9,
        );

        let ft = fourier_tempogram_from_envelope(env.view(), &FourierTempogramConfig::librosa())
            .unwrap();
        let shape = usizes(&g["fourier_shape"]);
        assert_eq!([ft.dim().1, ft.dim().2], [shape[0], shape[1]]);
        let mag = ft.slice(s![0, ..;bs, ..;fs]).mapv(|z| z.norm());
        check(
            &format!("fourier mag {sig}"),
            mag.as_slice().unwrap(),
            arr2(&g["fourier_mag"]).as_slice().unwrap(),
            1e-9,
        );
        let sub = ft.slice(s![0, ..;24, ..;8]).to_owned();
        let e = carr2(&g["fourier"]);
        let (ar, ai): (Vec<f64>, Vec<f64>) = sub.iter().map(|z| (z.re, z.im)).unzip();
        let (er, ei): (Vec<f64>, Vec<f64>) = e.iter().map(|z| (z.re, z.im)).unzip();
        check(&format!("fourier re {sig}"), &ar, &er, 1e-9);
        check(&format!("fourier im {sig}"), &ai, &ei, 1e-9);
        let cfg = FourierTempogramConfig::librosa()
            .with_win_length(nzu!(40))
            .with_center(false);
        let ft = fourier_tempogram_from_envelope(env.view(), &cfg).unwrap();
        let sub = ft.slice(s![0, ..;4, ..;4]).to_owned();
        let e = carr2(&g["fourier_w40_nocenter"]);
        assert_eq!(sub.dim(), e.dim());
        let (ar, ai): (Vec<f64>, Vec<f64>) = sub.iter().map(|z| (z.re, z.im)).unzip();
        let (er, ei): (Vec<f64>, Vec<f64>) = e.iter().map(|z| (z.re, z.im)).unzip();
        check(&format!("fourier w40 re {sig}"), &ar, &er, 1e-9);
        check(&format!("fourier w40 im {sig}"), &ai, &ei, 1e-9);
    }
    // Stereo from audio (onset envelope round-off adds ~1e-12).
    let tg = stereo().tempogram(&TempogramConfig::librosa()).unwrap();
    let shape = usizes(&f["stereo"]["tempogram_shape"]);
    assert_eq!(vec![tg.dim().0, tg.dim().1, tg.dim().2], shape);
    let sub = tg.slice(s![.., ..;16, ..;4]).to_owned();
    check(
        "tempogram stereo",
        sub.as_slice().unwrap(),
        arr3(&f["stereo"]["tempogram"]).as_slice().unwrap(),
        1e-9,
    );
}

#[test]
fn tempo_exact() {
    let f = &fixture()["tempo"];
    let srf = f64::from(sr());
    let hop = nzu!(512);
    for sig in ["clicks120", "notes", "mix"] {
        let g = &f[sig];
        let a = mono(sig);
        let env = a.onset_strength(&OnsetStrengthConfig::librosa()).unwrap();
        let t = |cfg: &TempoConfig| tempo_from_envelope(env.view(), srf, hop, cfg).unwrap();
        let d = TempoConfig::librosa();
        assert_eq!(t(&d)[[0, 0]], scalar(&g["default"]), "{sig} default");
        assert_eq!(
            a.tempo(&d).unwrap()[[0, 0]],
            scalar(&g["default"]),
            "{sig} trait"
        );
        assert_eq!(
            a.tempo(&d).unwrap()[[0, 0]],
            scalar(&g["from_y_f32basis"]),
            "{sig} f32 basis"
        );
        let tv = t(&d.clone().with_aggregate(None));
        assert_eq!(
            tv.row(0).to_vec(),
            f64s(&g["time_varying"]),
            "{sig} time varying"
        );
        let c = d
            .clone()
            .with_start_bpm(60.0)
            .with_std_bpm(0.5)
            .with_max_tempo(None)
            .with_ac_size(4.0);
        assert_eq!(
            t(&c)[[0, 0]],
            scalar(&g["start60_std05_nomax_ac4"]),
            "{sig} custom"
        );
        let c = d
            .clone()
            .with_aggregate(Some(Aggregate::Median))
            .with_max_tempo(Some(200.0));
        assert_eq!(t(&c)[[0, 0]], scalar(&g["median_max200"]), "{sig} median");
    }
    let st = stereo().tempo(&TempoConfig::librosa()).unwrap();
    assert_eq!(
        st.column(0).to_vec(),
        arr2(&f["stereo_f64"]["default"]).column(0).to_vec()
    );
    assert_eq!(
        st.column(0).to_vec(),
        arr2(&f["stereo"]["default"]).column(0).to_vec()
    );
}

#[test]
fn beat_track_exact() {
    let f = &fixture()["beat_track"];
    let srf = f64::from(sr());
    let hop = nzu!(512);
    for sig in ["clicks120", "notes", "mix"] {
        let g = &f[sig];
        let env = f64s(&g["envelope"]);
        let d = BeatTrackConfig::librosa();
        let run = |cfg: &BeatTrackConfig| beat_track_from_envelope(&env, srf, hop, cfg).unwrap();
        let cases = [
            ("default", d.clone()),
            ("no_trim", d.clone().with_trim(false)),
            ("tightness400", d.clone().with_tightness(400.0)),
            ("bpm100", d.clone().with_bpm(Some(100.0))),
            (
                "start90_tight50",
                d.clone().with_start_bpm(90.0).with_tightness(50.0),
            ),
        ];
        for (name, cfg) in &cases {
            let bt = run(cfg);
            assert_eq!(
                bt.beats.frames,
                usizes(&g[*name]["beats"]),
                "{sig} {name} beats"
            );
            assert_eq!(bt.tempo, scalar(&g[*name]["tempo"]), "{sig} {name} tempo");
        }
        assert_eq!(run(&d).beats.times(), f64s(&g["times"]), "{sig} times");
        // From audio: our envelope (f64 mel basis) and librosa's float32-basis run agree.
        let bt = mono(sig).beat_track(&d).unwrap();
        assert_eq!(
            bt.beats.frames,
            usizes(&g["default"]["beats"]),
            "{sig} trait"
        );
        assert_eq!(
            bt.beats.frames,
            usizes(&g["default_f32basis"]["beats"]),
            "{sig} f32 basis"
        );
        assert_eq!(
            bt.tempo,
            scalar(&g["default_f32basis"]["tempo"]),
            "{sig} f32 tempo"
        );
    }
    let g = &f["random"];
    let env = f64s(&g["envelope"]);
    let curve = f64s(&g["curve"]);
    let fr = srf / 512.0;
    let bt = beat_track_from_envelope(&env, srf, hop, &BeatTrackConfig::librosa()).unwrap();
    assert_eq!(bt.beats.frames, usizes(&g["default"]));
    assert_eq!(bt.tempo, scalar(&g["tempo"]));
    assert_eq!(
        beat_track_with_bpm(&env, &curve, fr, 100.0, true).unwrap(),
        usizes(&g["bpm_curve"])
    );
    assert_eq!(
        beat_track_with_bpm(&env, &curve, fr, 100.0, false).unwrap(),
        usizes(&g["bpm_curve_no_trim"])
    );
    assert_eq!(
        beat_track_with_bpm(&env, &[111.0], fr, 100.0, true).unwrap(),
        usizes(&g["bpm_odd_fpb"])
    );
}

#[test]
fn plp() {
    let f = &fixture()["plp"];
    let bt = &fixture()["beat_track"];
    let srf = f64::from(sr());
    let hop = nzu!(512);
    for sig in ["clicks120", "notes"] {
        let g = &f[sig];
        // librosa's own median envelope (stored with the beat-tracking cases).
        let e = f64s(&bt[sig]["envelope"]);
        let env = Array2::from_shape_vec((1, e.len()), e).unwrap();
        let cases = [
            ("default", PlpConfig::librosa()),
            (
                "range_60_200_w256",
                PlpConfig::librosa()
                    .with_tempo_range(Some(60.0), Some(200.0))
                    .with_win_length(nzu!(256)),
            ),
            (
                "unbounded",
                PlpConfig::librosa().with_tempo_range(None, None),
            ),
        ];
        for (name, cfg) in &cases {
            let p = plp_from_envelope(env.view(), srf, hop, cfg).unwrap();
            // FFT/ISTFT round-off on librosa's exact envelope (module doc).
            check(
                &format!("plp {sig} {name}"),
                p.as_slice().unwrap(),
                &f64s(&g[*name]),
                1e-9,
            );
        }
        let p = mono(sig).plp(&PlpConfig::librosa()).unwrap();
        check(
            &format!("plp {sig} from audio"),
            p.as_slice().unwrap(),
            &f64s(&g["default"]),
            1e-9,
        );
    }
}

#[test]
fn tempogram_variants() {
    let f = &fixture()["tempogram_variants"];
    let srf = f64::from(sr());
    let hop = nzu!(512);
    for sig in ["clicks120", "notes"] {
        let g = &f[sig];
        let e = f64s(&fixture()["tempogram"][sig]["envelope"]);
        let env = Array2::from_shape_vec((1, e.len()), e).unwrap();
        let tg = tempogram_from_envelope(env.view(), &TempogramConfig::librosa()).unwrap();

        // Linear interpolation of the tempogram at exact per-frame tempi: FFT round-off.
        let r = tempogram_ratio_from_tempogram(
            tg.view(),
            srf,
            hop,
            &TempogramRatioConfig::librosa(),
            None,
        )
        .unwrap();
        check(
            &format!("tempogram_ratio {sig}"),
            r.as_slice().unwrap(),
            arr2(&g["ratio"]).as_slice().unwrap(),
            1e-9,
        );
        let cfg = TempogramRatioConfig::librosa().with_aggregate(Some(Aggregate::Mean));
        let r = tempogram_ratio_from_tempogram(tg.view(), srf, hop, &cfg, None).unwrap();
        check(
            &format!("tempogram_ratio mean {sig}"),
            r.as_slice().unwrap(),
            &f64s(&g["ratio_mean"]),
            1e-9,
        );
        let mut cfg = TempogramRatioConfig::librosa().with_factors(vec![1.0, 0.5, 2.0]);
        cfg.tempo = cfg.tempo.with_start_bpm(90.0);
        cfg.fill_value = -1.0;
        let r = tempogram_ratio_from_tempogram(tg.view(), srf, hop, &cfg, None).unwrap();
        check(
            &format!("tempogram_ratio factors {sig}"),
            r.as_slice().unwrap(),
            arr2(&g["ratio_factors"]).as_slice().unwrap(),
            1e-9,
        );

        let h =
            hybrid_tempogram_from_envelope(env.view(), srf, hop, &HybridTempogramConfig::librosa())
                .unwrap();
        let shape = usizes(&g["hybrid_shape"]);
        assert_eq!([h.dim().1, h.dim().2], [shape[0], shape[1]]);
        let sub = h.slice(s![0, ..;8, ..;4]).to_owned();
        // sqrt(|F| * |A|): where the autocorrelation tempogram is zero in exact
        // arithmetic both sides hold FFT round-off (~1e-16 of the column peak), and the
        // square root turns it into sqrt(|F| * 1e-15) ~ 1e-7 absolute (|F| <= ~10).
        // Elsewhere the agreement is ~1e-15 relative (printed).
        let e = arr2(&g["hybrid"]);
        let (abs, rel) = errors(sub.iter(), e.iter());
        println!("hybrid {sig}: max abs {abs:.3e}, peak-rel {rel:.3e}");
        assert_close(&format!("hybrid {sig}"), sub.iter(), e.iter(), 1e-12, 2e-7);

        let ft = fourier_tempogram_from_envelope(env.view(), &FourierTempogramConfig::librosa())
            .unwrap();
        let n = ft.dim().2 - 1;
        let mag = ft.slice(s![.., .., ..n]).mapv(|z| z.norm());
        let freqs = fourier_tempo_frequencies(srf, hop, nzu!(384));
        let m = metrogram(mag.view(), &freqs, None, Aggregate::Sum, 0.0).unwrap();
        check(
            &format!("metrogram {sig}"),
            m.as_slice().unwrap(),
            arr2(&g["metrogram"]).as_slice().unwrap(),
            1e-9,
        );
        let m = metrogram(
            mag.view(),
            &freqs,
            Some(&[0.5, 1.0 / 3.0]),
            Aggregate::Max,
            0.0,
        )
        .unwrap();
        check(
            &format!("metrogram max {sig}"),
            m.as_slice().unwrap(),
            arr2(&g["metrogram_max"]).as_slice().unwrap(),
            1e-9,
        );
    }
}

/// A shared test signal as mono `f32` audio (exact: 16-bit PCM codes).
fn mono_f32(name: &str) -> AudioSamples<'static, f32> {
    let x: Vec<f32> = signal(name).iter().map(|&v| v as f32).collect();
    let rate = std::num::NonZeroU32::new(sr()).expect("sr > 0");
    AudioSamples::new_mono(ndarray::Array1::from(x), rate).expect("valid mono audio")
}

fn widen(x: impl IntoIterator<Item = f32>) -> Vec<f64> {
    x.into_iter().map(f64::from).collect()
}

/// `f32` audio against librosa run on `y.astype(np.float32)` (fixture
/// `float32.<sig>`). The outputs are computed in `f32` here.
#[test]
fn float32_input() {
    let f = &fixture()["float32"];
    for sig in ["clicks120", "notes", "mix"] {
        let g = &f[sig];
        let a = mono_f32(sig);

        let env = a.onset_strength(&OnsetStrengthConfig::librosa()).unwrap();
        check(
            &format!("f32 onset_strength {sig}"),
            &widen(env.iter().copied()),
            &f64s(&g["onset_strength"]),
            TOL_F32_ENVELOPE,
        );
        let median = OnsetStrengthConfig::librosa().with_aggregate(Some(Aggregate::Median));
        let env_m = a.onset_strength(&median).unwrap();
        check(
            &format!("f32 onset_strength median {sig}"),
            &widen(env_m.iter().copied()),
            &f64s(&g["onset_strength_median"]),
            TOL_F32_ENVELOPE,
        );

        let tg = a.tempogram(&TempogramConfig::librosa()).unwrap();
        let shape = usizes(&g["tempogram_shape"]);
        assert_eq!([tg.dim().1, tg.dim().2], [shape[0], shape[1]]);
        let sub = tg.slice(s![0, ..;8, ..;4]).to_owned();
        check(
            &format!("f32 tempogram {sig}"),
            &widen(sub.iter().copied()),
            arr2(&g["tempogram"]).as_slice().unwrap(),
            TOL_F32_TEMPOGRAM,
        );
        let ft = a
            .fourier_tempogram(&FourierTempogramConfig::librosa())
            .unwrap();
        let mag = ft.slice(s![0, ..;8, ..;4]).mapv(|z| f64::from(z.norm()));
        check(
            &format!("f32 fourier mag {sig}"),
            mag.as_slice().unwrap(),
            arr2(&g["fourier_mag"]).as_slice().unwrap(),
            TOL_F32_TEMPOGRAM,
        );
        let p = a.plp(&PlpConfig::librosa()).unwrap();
        check(
            &format!("f32 plp {sig}"),
            &widen(p.iter().copied()),
            &f64s(&g["plp"]),
            TOL_F32_PLP,
        );

        // Events and tempi: exact.
        assert_eq!(
            a.tempo(&TempoConfig::librosa()).unwrap()[[0, 0]],
            scalar(&g["tempo"]),
            "{sig} f32 tempo"
        );
        assert_eq!(
            a.onset_detect(&OnsetDetectConfig::librosa())
                .unwrap()
                .frames,
            usizes(&g["onset_detect"]),
            "{sig} f32 onset_detect"
        );
        for (key, cfg) in [
            ("beat_track", BeatTrackConfig::librosa()),
            (
                "beat_track_no_trim",
                BeatTrackConfig::librosa().with_trim(false),
            ),
        ] {
            let bt = a.beat_track(&cfg).unwrap();
            assert_eq!(bt.beats.frames, usizes(&g[key]["beats"]), "{sig} f32 {key}");
            assert_eq!(bt.tempo, scalar(&g[key]["tempo"]), "{sig} f32 {key} tempo");
        }
    }
}
